# SHA-256 first 4 constants and comparison hex constants
sha_constants_hex = [
    "428a2f98", "71374491", "b5c0fbcf", "e9b5dba5"
]

hex_constants_hex = [
    "AAAAAA", "BBBBBB", "CCCCCC", "DDDDDD"
]

# Convert to 32-bit binary
def hex_to_bin_32bit(hex_string):
    return format(int(hex_string, 16), '032b')

# Convert to 24-bit binary for comparison constants
def hex_to_bin_24bit(hex_string):
    return format(int(hex_string, 16), '024b')

sha_constants_bin = [hex_to_bin_32bit(h) for h in sha_constants_hex]
hex_constants_bin = [hex_to_bin_24bit(h) for h in hex_constants_hex]

import pandas as pd

# Prepare data for comparison
df = pd.DataFrame({
    "SHA Const (Hex)": sha_constants_hex,
    "SHA Const (Bin)": sha_constants_bin,
    "Grid Const (Hex)": hex_constants_hex,
    "Grid Const (Bin)": hex_constants_bin
})

import ace_tools as tools; tools.display_dataframe_to_user(name="SHA vs Grid Hex Bit Patterns", dataframe=df)

